package com.gameaggregator.apikeyservice.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="api_keys",indexes={@Index(name="idx_api_key_hash",columnList="keyHash",unique=true),@Index(name="idx_api_key_client",columnList="clientId")}) public class ApiKey{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID tenantId;@Column(nullable=false)public UUID clientId;@Column(nullable=false)public UUID environmentId;@Column(nullable=false,unique=true,length=64)public String keyHash;@Column(nullable=false,length=16)public String keyPrefix;@Column(nullable=false,length=4)public String lastFour;@Lob @Column(nullable=false)public String scopesJson;@Lob @Column(nullable=false)public String ipAllowlistJson;@Column(nullable=false)public long quota;@Column(nullable=false)public String status="ACTIVE";public Instant expiresAt;public Instant revokedAt;@Column(nullable=false)public Instant createdAt=Instant.now();public Instant rotatedAt;@Version public long version;protected ApiKey(){}public ApiKey(UUID t,UUID c,UUID e,String h,String p,String l,String s,String i,long q,Instant x){tenantId=t;clientId=c;environmentId=e;keyHash=h;keyPrefix=p;lastFour=l;scopesJson=s;ipAllowlistJson=i;quota=q;expiresAt=x;}}